// Shared catalogue overrides and explicit links use the same PIN as existing research.
function subjectFieldFor(person){
 if(person.kind==='topic')return 'traits';
 if(person.kind==='history')return 'history';
 if(person.kind==='prophecy')return 'prophecy';
 if(!person.kind&&new URLSearchParams(location.hash.split('?')[1]||'').get('from')==='history')return 'history';
 return '';
}
function subjectOverride(field,name){return personalCatalog.find(x=>x.field===field&&x.name===name)}
function subjectVisible(field,name){return !subjectOverride(field,name)?.hidden}
function personalHistoryTime(name){const item=subjectOverride('history',name);if(item)return item.time_label||'';for(const [,rows] of studyHistory){const row=rows.find(x=>x[0]===name);if(row)return row[2]||''}return ''}
function customSubjects(field){return personalCatalog.filter(x=>x.field===field&&!x.hidden)}
function explicitTargets(noteId){return personalLinks.filter(x=>x.note_id===noteId).map(x=>x.target_key)}
function noteHasSubject(noteId,key){return personalLinks.some(x=>x.note_id===noteId&&x.target_key===key)}
function personalSubjectKey(name,kind){return kind==='person'?name:'@'+kind+':'+name}
function subjectChoices(){
 const result=[];const add=(group,name,key)=>{if(!result.some(x=>x.group===group&&x.key===key))result.push({group,name,key})};
 allPeople().forEach(p=>add('인물',displayName(p.name),p.name));
 [...fruitTraits,...otherTraits].filter(n=>subjectVisible('traits',n)).forEach(n=>add('특성',n,'@topic:'+n));
 customSubjects('traits').forEach(x=>add('특성',x.name,'@topic:'+x.name));
 bibleBooks.forEach(b=>add('성경',b[0],'@book:'+b[0]));
 studyHistory.forEach(([,items])=>items.filter(([n])=>subjectVisible('history',n)).forEach(([n,k])=>add('역사',n,personalSubjectKey(n,k))));
 customSubjects('history').forEach(x=>add('역사',x.name,'@history:'+x.name));
 studyProphecies.filter(([n])=>subjectVisible('prophecy',n)).forEach(([n])=>add('예언',n,'@prophecy:'+n));
 customSubjects('prophecy').forEach(x=>add('예언',x.name,'@prophecy:'+x.name));
 return result;
}
function showPersonalError(node,error){node.textContent=error?.message||'저장하지 못했어요. 다시 시도해 주세요.'}
// Verify directly in the existing on-screen keypad: no intermediate confirmation sheet.
function personalWithPin(run){return new Promise(resolve=>{const input=document.createElement('input');input.type='password';input.readOnly=true;input.style.cssText='position:fixed;left:-10000px;width:1px;height:1px';document.body.append(input);let result=null;openPinPad(input,{onComplete:async pin=>{const value=await run(pin);if(!value?.ok)throw Error(value?.error||'저장하지 못했어요.');result=value},onClose:()=>{input.remove();resolve(result)}})})}
async function personalRequestPin(){const result=await personalWithPin(async pin=>({ok:true,pin}));return result?.pin??null}

function openPersonalAdd(field,existingName=null){
 const labels={traits:'특성',history:'역사',prophecy:'예언'},label=labels[field];if(!label)return;
 const d=document.createElement('dialog');d.className='personal-edit-dialog';d.innerHTML=`<form class="personal-edit-form"><div class="personal-edit-head"><h2>${label} ${existingName?'수정':'추가'}</h2><button type="button" data-close aria-label="닫기">×</button></div><label>이름<input name="name" maxlength="75" required autocomplete="off"></label>${field==='history'?`<label>시대<select name="era"><option value="시기 미상">시기 미상</option>${studyHistory.map(x=>`<option>${esc(x[0])}</option>`).join('')}<option value="그 이후">그 이후</option></select></label><label>시기 <small>선택 사항</small><span class="personal-date-row"><select name="epoch" aria-label="기원 선택"><option value="bc">기원전</option><option value="ad">기원</option></select><input name="year" type="number" inputmode="numeric" min="1" max="9999" step="1" placeholder="연도" aria-label="연도"><span>년</span></span></label><label>끝 시기 <small>선택 사항</small><span class="personal-date-row"><select name="end_epoch" aria-label="끝 시기의 기원 선택"><option value="bc">기원전</option><option value="ad">기원</option></select><input name="end_year" type="number" inputmode="numeric" min="1" max="9999" step="1" placeholder="연도" aria-label="끝 연도"><span>년</span></span></label><label class="personal-approx"><input name="approx" type="checkbox"> 대략적인 시기</label>`:''}${field==='prophecy'?'<label>대표 성구 <small>선택 사항</small><input name="verse" maxlength="100" placeholder="예: 다니엘 2:31-45"></label>':''}<p class="personal-edit-error" role="status"></p><button type="submit" class="primary">${existingName?'저장':'추가'}</button></form>`;
 document.body.append(d);d.querySelector('[data-close]').onclick=()=>d.close();d.addEventListener('close',()=>d.remove(),{once:true});d.showModal();
 if(existingName){const f=d.querySelector('form'),item=subjectOverride(field,existingName);f.elements.name.value=existingName;f.elements.name.readOnly=true;if(field==='history'){const base=studyHistory.find(([,items])=>items.some(x=>x[0]===existingName)),row=base?.[1].find(x=>x[0]===existingName);f.elements.era.value=item?.era||base?.[0]||'시기 미상';const date=item?.time_label||row?.[2]||'',m=date.match(/^(기원전|기원) (\d+)년(?:~(기원전|기원) (\d+)년)?(경)?$/);if(m){f.elements.epoch.value=m[1]==='기원전'?'bc':'ad';f.elements.year.value=m[2];if(m[3]){f.elements.end_epoch.value=m[3]==='기원전'?'bc':'ad';f.elements.end_year.value=m[4]}f.elements.approx.checked=!!m[5]}}if(field==='prophecy')f.elements.verse.value=item?.verse??studyProphecies.find(x=>x[0]===existingName)?.[1]??''}
 d.querySelector(existingName&&field==='prophecy'?'[name=verse]':'[name=name]').focus();
 d.querySelector('form').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget,name=f.elements.name.value.trim(),error=d.querySelector('.personal-edit-error'),save=f.querySelector('[type=submit]');if(!name)return;const exists=!existingName&&subjectChoices().some(x=>x.group===label&&x.name===name);if(exists){error.textContent='이미 있는 항목이에요.';return}const data={field,name};if(field==='history'){let year=f.elements.year.value?Number(f.elements.year.value):null,end=f.elements.end_year.value?Number(f.elements.end_year.value):null;data.era=f.elements.era.value;if((year||end)&&data.era==='시기 미상'){error.textContent='시기를 넣었다면 시대도 선택해 주세요.';return}if(end&&!year){error.textContent='시작 연도도 입력해 주세요.';return}let startSort=year?(f.elements.epoch.value==='bc'?-year:year):null,endSort=end?(f.elements.end_epoch.value==='bc'?-end:end):null;if(endSort!==null&&endSort<startSort){error.textContent='끝 연도가 시작 연도보다 앞서요.';return}data.sort_year=startSort;data.time_label=year?(f.elements.epoch.value==='bc'?'기원전 ':'기원 ')+year+'년'+(end?'~'+(f.elements.end_epoch.value==='bc'?'기원전 ':'기원 ')+end+'년':'')+(f.elements.approx.checked?'경':''):''}if(field==='prophecy')data.verse=f.elements.verse.value.trim();save.disabled=true;try{const r=await personalWithPin(pin=>rpc('study_subject_catalog_change',{p_password:pin,p_action:'save',p_data:data}));if(!r)return;personalCatalog=await getAll('study_subject_catalog');if(field==='prophecy'){if(data.verse)representatives['@prophecy:'+name]=data.verse;else delete representatives['@prophecy:'+name]}d.close();if(existingName)personView(currentPerson);else renderPeopleResults()}catch(err){showPersonalError(error,err)}finally{save.disabled=false}};
}
async function removePersonalSubject(field,name){
 if(!confirm('목록에서 이 항목을 지울까요? 연결된 연구 기록은 그대로 남아요.'))return;
 try{const r=await personalWithPin(pin=>rpc('study_subject_catalog_change',{p_password:pin,p_action:'hide',p_data:{field,name}}));if(!r)return;personalCatalog=await getAll('study_subject_catalog');location.hash='#/people?field='+field}catch(err){alert(err.message||'삭제하지 못했어요. 다시 시도해 주세요.')}
}
function noteLinksMarkup(n){if(familyInternal(n))return '';const targets=explicitTargets(n.id);return `<div class="personal-note-links">${targets.length?`<div class="personal-note-link-list">${targets.map(key=>`<a href="${idHash(key)}">${esc(displayName(key))}</a>`).join('')}</div>`:''}<button type="button" class="link" data-study-links="${esc(n.id)}">${targets.length?'연구 연결 수정':'+ 연구 연결'}</button></div>`}
function bindPersonalLinks(){document.querySelectorAll('[data-study-links]').forEach(b=>b.onclick=()=>openPersonalLinks(b.dataset.studyLinks))}
function openPersonalLinks(noteId){
 const note=notes.find(n=>n.id===noteId);if(!note)return;const original=explicitTargets(noteId).sort(),implied=new Set([note.person,...(note.book?['@book:'+note.book]:[]),...(note.topic||'').split(',').map(x=>x.trim()).filter(Boolean).map(x=>'@topic:'+x)]),selected=new Set(original.filter(x=>!implied.has(x))),choices=subjectChoices().filter(x=>!implied.has(x.key)),known=new Set(choices.map(x=>x.key));original.filter(x=>!known.has(x)&&!implied.has(x)).forEach(x=>choices.push({group:'기타',name:displayName(x),key:x}));
 const d=document.createElement('dialog');d.className='personal-edit-dialog';d.innerHTML=`<form class="personal-edit-form personal-links-form"><div class="personal-edit-head"><h2>연구 연결</h2><button type="button" data-close aria-label="닫기">×</button></div><label>분야<select name="group"><option>인물</option><option>특성</option><option>성경</option><option>역사</option><option>예언</option><option>기타</option></select></label><label>이름 찾기<input name="search" type="search" autocomplete="off" placeholder="이름을 입력하세요"></label><div class="personal-link-choices" aria-label="연구 대상"></div><p class="personal-link-count" aria-live="polite"></p><p class="personal-edit-error" role="status"></p><button type="submit" class="primary">완료</button></form>`;document.body.append(d);d.querySelector('[data-close]').onclick=()=>d.close();d.addEventListener('close',()=>d.remove(),{once:true});d.showModal();const form=d.querySelector('form'),list=d.querySelector('.personal-link-choices');
 function draw(){const q=form.elements.search.value.trim().toLocaleLowerCase(),group=form.elements.group.value,visible=choices.filter(x=>x.group===group&&(!q||x.name.toLocaleLowerCase().includes(q)));list.innerHTML=visible.map(x=>`<label><input type="checkbox" value="${esc(x.key)}" ${selected.has(x.key)?'checked':''}><span>${esc(x.name)}</span></label>`).join('')||'<p class="personal-link-empty">일치하는 항목이 없어요.</p>';d.querySelector('.personal-link-count').textContent=selected.size?'선택 '+selected.size+'개':'';list.querySelectorAll('input').forEach(input=>input.onchange=()=>{input.checked?selected.add(input.value):selected.delete(input.value);d.querySelector('.personal-link-count').textContent=selected.size?'선택 '+selected.size+'개':''})}
 form.elements.group.onchange=draw;let composing=false;form.elements.search.addEventListener('compositionstart',()=>composing=true);form.elements.search.addEventListener('compositionend',()=>{composing=false;draw()});form.elements.search.oninput=()=>{if(!composing)draw()};draw();
 form.onsubmit=async e=>{e.preventDefault();const targets=[...new Set([...selected,...original.filter(x=>implied.has(x))])].sort(),error=d.querySelector('.personal-edit-error'),save=form.querySelector('[type=submit]');if(JSON.stringify(targets)===JSON.stringify(original)){d.close();return}save.disabled=true;try{const r=await personalWithPin(async pin=>{const value=await rpc('study_note_subject_links_save',{p_password:pin,p_note:noteId,p_targets:targets,p_expected:original});if(value?.conflict){personalLinks=await getAll('study_note_subject_links');throw Error('다른 기기에서 연결이 바뀌었어요. 닫고 다시 열어 주세요.')}return value});if(!r)return;personalLinks=await getAll('study_note_subject_links');d.close();personView(currentPerson);document.getElementById('note-'+noteId)?.scrollIntoView({block:'center'})}catch(err){showPersonalError(error,err)}finally{save.disabled=false}};
}

// Validate optional version-3 metadata before attempting any restore.
function validatePersonalBackup(data,backupNotes){
 if(!data||typeof data!=="object"||!Array.isArray(data.subjects)||!Array.isArray(data.links)||data.subjects.length>10000||data.links.length>100000)throw Error('개인 연구 백업을 확인해 주세요.');
 const fields=new Set(['traits','history','prophecy']),ids=new Set(),seenIds=new Set(),uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
 for(const note of backupNotes){if(note?.id){if(seenIds.has(note.id))throw Error('백업에 같은 기록 번호가 두 번 있습니다.');seenIds.add(note.id);ids.add(note.id)}}
 const subjects=new Set();for(const x of data.subjects){if(!x||typeof x!=="object"||!fields.has(x.field)||typeof x.name!=="string"||!x.name.trim()||x.name!==x.name.trim()||x.name.length>75||[x.era,x.time_label,x.verse].some(v=>v!=null&&(typeof v!=="string"||v.length>100))||(x.hidden!==undefined&&typeof x.hidden!=="boolean")||(x.sort_year!=null&&(!Number.isInteger(x.sort_year)||!x.sort_year||Math.abs(x.sort_year)>9999))||[x.created_at,x.updated_at].some(v=>v!=null&&(typeof v!=="string"||!Number.isFinite(Date.parse(v)))))throw Error('개인 연구 항목을 확인해 주세요.');const key=x.field+'\u0000'+x.name;if(subjects.has(key))throw Error('백업에 같은 연구 항목이 두 번 있습니다.');subjects.add(key)}
 const links=new Set();for(const x of data.links){if(!x||typeof x!=="object"||typeof x.note_id!=="string"||!uuid.test(x.note_id)||!ids.has(x.note_id)||typeof x.target_key!=="string"||!x.target_key.trim()||x.target_key.length>100)throw Error('백업의 연구 연결을 확인해 주세요.');const key=x.note_id+'\u0000'+x.target_key;if(links.has(key))throw Error('백업에 같은 연구 연결이 두 번 있습니다.');links.add(key)}
}
